export type OfertyRow = {
  id: string;
  numer_oferty: string;
  teczka_odnosnik: string;
  rodzaj_oferty: "sprzedaz" | "najem" | "sprzedaz_i_najem";
  rodzaj_nieruchomosci: "lokal" | "dom_z_dzialka" | "dzialka" | "spoldzielcze_prawo_do_lokalu";
  wersja_id: number;
  wersja_od: string;
  powierzchnia: number;
  lokalizacja_przyblizona: string;
  cena_sprzedazy: number | null;
  czynsz: number | null;
  opis: string;
  zdjecia_sciezka: string | null;
  widocznosc: "publiczna" | "niepubliczna";
  granice_zgody: string | null;
  wylacznosc: boolean;
  status: "aktywna" | "zarezerwowana" | "sprzedana_albo_wynajeta" | "wycofana";
  status_od: string;
};

/**
 * Oferty katalogu z bieżącą wersją i bieżącym statusem, w kolejności wpisania. Opiekun
 * poszukującego proponuje tylko aktywne, a zarezerwowane z informacją o rezerwacji; niepubliczną
 * pokazuje tylko w granicach zgody.
 */
export const oferty: XMetaQuery<null, OfertyRow, "many"> = {
  kind: katalogOfertOferty,
  name: "oferty",
  sql: `SELECT
  wpisy.id,
  wpisy.numer_oferty,
  wpisy.teczka_odnosnik,
  wpisy.rodzaj_oferty,
  wpisy.rodzaj_nieruchomosci,
  wersje.id AS wersja_id,
  wersje.od AS wersja_od,
  wersje.powierzchnia,
  wersje.lokalizacja_przyblizona,
  wersje.cena_sprzedazy,
  wersje.czynsz,
  wersje.opis,
  wersje.zdjecia_sciezka,
  wersje.widocznosc,
  wersje.granice_zgody,
  wersje.wylacznosc,
  statusy.status,
  statusy.od AS status_od
FROM katalog_ofert_oferty_wpisy AS wpisy
JOIN katalog_ofert_oferty_wersje AS wersje ON wersje.oferta_id = wpisy.id
  AND wersje.id = (
    SELECT max(id)
    FROM katalog_ofert_oferty_wersje
    WHERE oferta_id = wpisy.id
  )
JOIN katalog_ofert_oferty_statusy AS statusy ON statusy.oferta_id = wpisy.id
  AND statusy.id = (
    SELECT max(id)
    FROM katalog_ofert_oferty_statusy
    WHERE oferta_id = wpisy.id
  )
ORDER BY wpisy.rowid`,
  parameters: [],
  returns: "many",
  booleanColumns: ["wylacznosc"],
};

/**
 * Oferty katalogu z bieżącą wersją i bieżącym statusem, w kolejności wpisania. Opiekun
 * poszukującego proponuje tylko aktywne, a zarezerwowane z informacją o rezerwacji; niepubliczną
 * pokazuje tylko w granicach zgody.
 */
export function useOferty(): MetaState<OfertyRow[]> {
  return useMetaQuery(oferty);
}

